assert_throws_js: function "function () {
          response.body.getReader();
        }" did not throw

assert_throws_quotaexceedederror: function "() => {
    fetchLater(requestUrl, {
      activateAfter: 0,
      method: 'POST',
      body: generatePayload(
          getRemainingQuota(QUOTA_PER_ORIGIN, requestUrl, headers) + 1,
          dataType),
      referrer: '',
    });
  }" threw object "ReferenceError: fetchLater is not defined" that is not a correct QuotaExceededError: property "code" is equal to undefined, expected 22

assert_throws_quotaexceedederror: function "() => {
      fetchLater('/', {
        activateAfter: 0,
        method: 'POST',
        body: makeBeaconData(
            generatePayload(OVERSIZED_REQUEST_BODY_SIZE), dataType),
        referrer: '',
      });
      // It is difficult to compute the exact requested length, as that depends on
      // the datatype. Instead, it should always be more than `OVERSIZED_REQUEST_BODY_SIZE`
      // since we count url and referrer as well
    }" threw object "ReferenceError: fetchLater is not defined" that is not a correct QuotaExceededError: property "code" is equal to undefined, expected 22

assert_throws_js: the constructor should throw function "() => new TextDecoderStream({
    toString() { return {}; }
  })" threw object "ReferenceError: TextDecoderStream is not defined" ("ReferenceError") expected instance of function "function TypeError() { [native code] }" ("TypeError")

assert_throws_js: the constructor should throw function "() => new TextDecoderStream('utf-8', {
                     get fatal() { throw new Error(); }
                   })" threw object "ReferenceError: TextDecoderStream is not defined" ("ReferenceError") expected instance of function "function Error() { [native code] }" ("Error")

assert_throws_js: the constructor should throw function "() => new TextDecoderStream('utf-8', {
                     get ignoreBOM() { throw new Error(); }
                   })" threw object "ReferenceError: TextDecoderStream is not defined" ("ReferenceError") expected instance of function "function Error() { [native code] }" ("Error")

